import React, { useEffect, useState } from "react";
import { portalApi } from "../services/portalApi";

function Card({ title, action, children }) {
  return (
    <div
      style={{
        background: "white",
        border: "1px solid #e2e8f0",
        borderRadius: 16,
        padding: 16,
      }}
    >
      <div
        style={{
          fontWeight: 900,
          marginBottom: 12,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 12,
        }}
      >
        <div>{title}</div>
        {action ? <div>{action}</div> : null}
      </div>

      {children}
    </div>
  );
}

const btnDark = {
  borderRadius: 14,
  border: "1px solid #0f172a",
  background: "#0f172a",
  color: "white",
  padding: "10px 18px",
  fontWeight: 900,
  cursor: "pointer",
  boxShadow: "0 1px 0 rgba(0,0,0,0.15)",
};

const btnDanger = {
  borderRadius: 12,
  border: "1px solid #ef4444",
  background: "#ef4444",
  color: "white",
  padding: "10px 12px",
  fontWeight: 900,
  cursor: "pointer",
};

export default function AdminDashboard() {
  const [students, setStudents] = useState([]);

  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phone, setPhone] = useState("");
  const [address, setAddress] = useState("");

  const [confirmId, setConfirmId] = useState(null);

  const load = async () => {
    const list = await portalApi.getStudents();
    setStudents(list);
  };

  useEffect(() => {
    load();
  }, []);

  const add = async () => {
    const fn = firstName.trim();
    const ln = lastName.trim();
    const ph = phone.trim();
    const ad = address.trim();

    if (!fn || !ln || !ph || !ad) return;

    await portalApi.addStudent({
      firstName: fn,
      lastName: ln,
      phone: ph,
      address: ad,
    });

    setFirstName("");
    setLastName("");
    setPhone("");
    setAddress("");

    await load();
  };

  const confirmDelete = async () => {
    if (!confirmId) return;
    await portalApi.deleteStudent(confirmId);
    setConfirmId(null);
    await load();
  };

  const canAdd =
    firstName.trim() && lastName.trim() && phone.trim() && address.trim();

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <Card
        title="Admin — Add Student"
        action={
          <button onClick={load} type="button" style={btnDark}>
            Refresh
          </button>
        }
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
            gap: 10,
            alignItems: "end",
          }}
        >
          <label style={{ display: "grid", gap: 6 }}>
            <span style={{ fontSize: 12, color: "#64748b", fontWeight: 800 }}>
              First name
            </span>
            <input
              value={firstName}
              onChange={(e) => setFirstName(e.target.value)}
              style={{
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                padding: "10px 12px",
              }}
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span style={{ fontSize: 12, color: "#64748b", fontWeight: 800 }}>
              Last name
            </span>
            <input
              value={lastName}
              onChange={(e) => setLastName(e.target.value)}
              style={{
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                padding: "10px 12px",
              }}
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span style={{ fontSize: 12, color: "#64748b", fontWeight: 800 }}>
              Phone
            </span>
            <input
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              style={{
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                padding: "10px 12px",
              }}
            />
          </label>

          <label style={{ display: "grid", gap: 6 }}>
            <span style={{ fontSize: 12, color: "#64748b", fontWeight: 800 }}>
              Address
            </span>
            <input
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              style={{
                borderRadius: 12,
                border: "1px solid #e2e8f0",
                padding: "10px 12px",
              }}
            />
          </label>

          <button
            onClick={add}
            type="button"
            disabled={!canAdd}
            style={{
              borderRadius: 12,
              border: "1px solid #0f172a",
              background: canAdd ? "#0f172a" : "#94a3b8",
              color: "white",
              padding: "10px 12px",
              fontWeight: 900,
              cursor: canAdd ? "pointer" : "not-allowed",
            }}
          >
            Add
          </button>
        </div>
      </Card>

      <Card title="Current Students">
        <div style={{ display: "grid", gap: 8 }}>
          {students.map((s) => (
            <div
              key={s.id}
              style={{
                display: "grid",
                gridTemplateColumns: "80px 1fr 150px",
                gap: 10,
                alignItems: "center",
                border: "1px solid #e2e8f0",
                borderRadius: 12,
                padding: 10,
              }}
            >
              <div style={{ fontWeight: 900 }}>{s.id}</div>

              <div style={{ display: "grid", gap: 2 }}>
                <div style={{ fontWeight: 800 }}>
                  {s.firstName} {s.lastName}
                </div>
                <div style={{ fontSize: 12, color: "#64748b" }}>
                  {s.phone || "—"} • {s.address || "—"}
                </div>
              </div>

              <button
                type="button"
                onClick={() => setConfirmId(s.id)}
                style={{ ...btnDanger, justifySelf: "end" }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      </Card>

      {/* CSS confirm modal */}
      {confirmId && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(15,23,42,0.6)",
            display: "grid",
            placeItems: "center",
            zIndex: 50,
            padding: 16,
          }}
          onClick={() => setConfirmId(null)} // click outside closes
        >
          <div
            onClick={(e) => e.stopPropagation()} // prevent closing when clicking inside
            style={{
              width: "100%",
              maxWidth: 380,
              background: "white",
              borderRadius: 16,
              border: "1px solid #e2e8f0",
              padding: 20,
              boxShadow: "0 10px 30px rgba(0,0,0,.15)",
            }}
          >
            <div style={{ fontWeight: 900, fontSize: 18 }}>Delete student?</div>
            <div style={{ marginTop: 8, fontSize: 14, color: "#64748b" }}>
              This action cannot be undone.
            </div>

            <div
              style={{
                marginTop: 18,
                display: "flex",
                justifyContent: "flex-end",
                gap: 10,
              }}
            >
              <button
                type="button"
                onClick={() => setConfirmId(null)}
                style={{
                  borderRadius: 12,
                  border: "1px solid #e2e8f0",
                  background: "white",
                  padding: "10px 12px",
                  fontWeight: 900,
                  cursor: "pointer",
                }}
              >
                Cancel
              </button>

              <button type="button" onClick={confirmDelete} style={btnDanger}>
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
